const fs = require('fs');
const src = process.argv[2];
const dst = process.argv[3];
let s = fs.readFileSync(src, 'utf8');
const m = s.match(/data:image\/gif;base64,([A-Za-z0-9+/=]+)/);
if (!m) { console.error('NO_DATA in ' + src); process.exit(1); }
fs.writeFileSync(dst, Buffer.from(m[1], 'base64'));
console.log('OK bytes=' + Buffer.from(m[1], 'base64').length);

